def make(n):
    # Return a list with a single argument list; the benchmark will invoke the target n times.
    pattern = "foo"
    return [[pattern]] * min(n, 8)

def make(n):
    # generate n different harmless patterns that are valid regexes
    return [[f"literal_pat_{i}"] for i in range(n)]

def make(n):
    # generate n different patterns that are all valid regexes
    return [[f"pat{i}"] for i in range(n)]
